37	{"ts": "2026-11-02T23:05:35+00:00", "session": "86c85aab-2d5e-4443-b1f6-102edafedb26", "agent": "main", "tool": "run_select", "server": "legacy-sql", "sql": "SELECT 'prv_pais' AS campo, prv_pais AS valor, count(*) AS filas FROM prvmst GROUP BY prv_pais UNION ALL SELECT 'art_lin', art_lin, count(*) FROM artmst GROUP BY art_lin UNION ALL SELECT 'mov_tip', mov_tip, count(*) FROM movinv GROUP BY mov_tip UNION ALL SELECT 'ocp_sts', ocp_sts, count(*) FROM ocpcab GROUP BY ocp_sts ORDER BY campo, valor", "args": null, "ok": true, "rows": 18, "truncated": false, "error": null}
38	{"ts": "2026-11-02T23:05:35+00:00", "session": "86c85aab-2d5e-4443-b1f6-102edafedb26", "agent": "main", "tool": "run_select", "server": "legacy-sql", "sql": "SELECT m.mov_id, m.mov_art, m.mov_alm, m.mov_qty, e.exi_qty AS stock_actual FROM movinv m JOIN exidet e ON e.exi_art = m.mov_art AND e.exi_alm = m.mov_alm WHERE m.mov_tip = 'SAL' AND m.mov_qty > e.exi_qty ORDER BY m.mov_id", "args": null, "ok": true, "rows": 1, "truncated": false, "error": null}
39	{"ts": "2026-11-02T23:05:54+00:00", "session": "86c85aab-2d5e-4443-b1f6-102edafedb26", "agent": "main", "tool": "run_select", "server": "legacy-sql", "sql": "SELECT count(*) AS articulos, round(min(art_ptr / art_cst), 2) AS razon_min, round(avg(art_ptr / art_cst), 2) AS razon_media, round(max(art_ptr / art_cst), 2) AS razon_max, count(*) FILTER (WHERE art_ptr < art_cst) AS ptr_menor_que_costo, round(corr(art_ptr, art_cst)::numeric, 3) AS correlacion FROM artmst WHERE art_cst > 0", "args": null, "ok": true, "rows": 1, "truncated": false, "error": null}
40	{"ts": "2026-11-02T23:05:55+00:00", "session": "86c85aab-2d5e-4443-b1f6-102edafedb26", "agent": "main", "tool": "run_select", "server": "legacy-sql", "sql": "SELECT p.prv_pais, count(*) AS articulos, min(a.art_cst) AS costo_min, max(a.art_cst) AS costo_max FROM artmst a JOIN prvmst p ON p.prv_id = a.art_prv GROUP BY p.prv_pais ORDER BY p.prv_pais", "args": null, "ok": true, "rows": 7, "truncated": false, "error": null}
41	{"ts": "2026-11-02T23:05:56+00:00", "session": "86c85aab-2d5e-4443-b1f6-102edafedb26", "agent": "main", "tool": "run_select", "server": "legacy-sql", "sql": "SELECT art_cd, art_lin, art_cst, art_ptr, art_crt, art_prv FROM artmst WHERE art_cd = 'SKU-0009'", "args": null, "ok": true, "rows": 1, "truncated": false, "error": null}
42	{"ts": "2026-11-02T23:05:56+00:00", "session": "86c85aab-2d5e-4443-b1f6-102edafedb26", "agent": "main", "tool": "run_select", "server": "legacy-sql", "sql": "SELECT mov_id, mov_art, mov_alm, mov_tip, mov_qty, mov_fch FROM movinv WHERE mov_id = 28", "args": null, "ok": true, "rows": 1, "truncated": false, "error": null}
43	{"ts": "2026-11-02T23:06:01+00:00", "session": "86c85aab-2d5e-4443-b1f6-102edafedb26", "agent": "main", "tool": "run_select", "server": "legacy-sql", "sql": "WITH v AS (SELECT vta_art, sum(vta_und) AS vendido FROM vtadia GROUP BY vta_art), s AS (SELECT exi_art, sum(exi_qty) AS stock FROM exidet GROUP BY exi_art) SELECT count(*) AS articulos, round(corr(a.art_ptr, v.vendido)::numeric, 3) AS corr_ptr_ventas, round(corr(a.art_ptr, s.stock)::numeric, 3) AS corr_ptr_stock, count(*) FILTER (WHERE s.stock < a.art_ptr) AS articulos_bajo_ptr, count(*) FILTER (WHERE s.stock < a.art_ptr AND a.art_crt) AS criticos_bajo_ptr FROM artmst a JOIN v ON v.vta_art = a.art_cd JOIN s ON s.exi_art = a.art_cd", "args": null, "ok": true, "rows": 1, "truncated": false, "error": null}
